9287f7ca: ;
 .;Transcript Display
 .;
 .;The following lines are to check the status of a transcript
 .;and determine if the transcript should be flagged
 .;
 .;Get pertinent transcript variable values and set status flag(DGJTFLAG)
 .;to determine if the transcript should be flagged for display.
 .;
 .;Node 0:  IFN=Internal entry reference in file 393
 .;         DGJTNODE=zero node of transcript entry
 .;         DGJTDEL=associated 40.8 entry from word-processing package
 .;         DGJTPAR=pieces 6-8 of 40.8 entry

830eb231:  .;
 .;Check if transcript status = INCOMPLETE
 .;
 .;Get timestamp of sent to transcription and parse timelimit
 .;  parameter of dictated -> transcribed
 .;Set status flag if timestamp is:
 .;  1) prior to but in same month as today; or
 .;  2) earlier than X month(s) ago as defined by timelimit parameter
 .;
 .;Calculate days late if flagged
 .;
 .;Exit if not flagged

34ccf893:  .;
 .;Check if transcript status = TRANSCRIBED
 .;
 .;Get timestamp of transcription complete and parse timelimit
 .;  parameter of transcribed -> signed
 .;Set status flag if timestamp is NOT less than timelimit
 .;
 .;Calculate days late if flagged
 .;Exit

f7bc5aff: ;
 .;If transcript status = SIGNED and timelimit parameter is defined
 .;
 .;Get timestamp of transcript signature and parse timelimit parameter
 .;Set status flag if timestamp is NOT less than timelimit
 .;
 .;Calculate days late if flagged
 .;Exit
